"""Make models generated by LocalSpawn (Hunyuan3D + UltraTex GLBs) game-ready for Safe Haven's gathering nodes.

LocalSpawn makes the shape and its colour, normal and ORM maps from a concept image; this does what the game needs on
top (see the asset principles), so AgentScripts/BuildGatheringModels.cs takes the result like any other asset:

- each GLB becomes one look ("<Asset> A", "B", ...): scaled so its widest side is the size given, turned about the
  vertical, its pivot on the ground under its middle, lowest point on the ground;
- its small holes are closed and its specks cleared (mesh_repair.py: generated meshes arrive with dozens of open
  borders), before anything is decimated or baked; what is still open is written to <Asset>_Budget.json;
- two levels of detail ("<look> LOD1", "LOD2", decimated) and a convex "<look> Collider";
- the looks share one texture set: their own maps are baked into a shared atlas (2048), and Height (parallax) and
  BlendMask (curvature, edge wear, cavity, coverage: where the live moss grows) are baked from the mesh (prop_bake.py).

Writes Assets/_Project/Art/Gathering/<Asset>/ (<Asset>.fbx, _Albedo, _Normal, _ORM, _Height, _BlendMask and, with
--glow, _Emission) and a preview render beside the GLBs.

A manifest "remove" ([[x0, x1, y0, y1, z0, z1], ...]) cuts the faces in those boxes away first (the barrow's crossbar,
where the game mounts its wheel). Wheeled things (the carts, transport_manifest.json): the manifest's "wheels" mark where each generated wheel is
([{"hub": [x, y, z], "radius": r, "width": w}], the axle along x, in the look's own ground coordinates). Each is cut out
of the generated mesh before anything else into its own look "<look> Wheel N", baked into the same atlas in place (so
nothing of the body shades it: it turns), then centred on its hub, the hub found from the cut wheel itself, and put
there: Unity reads the hub from the model's node and the radius from the mesh.

Glowing things (moonsilver, deepstone, the Life Orbs) glow where their albedo is close to a colour or bright
(--glow-json '{"mode": "hue"|"bright", "colour": [r,g,b], "tint": [r,g,b], "threshold": 0-1}'): the generated
textures carry no emission, so it is made from the albedo after the bake.

Run: blender -b --factory-startup --python Tools/Blender/ingest_generated.py -- <project root> <asset name> <width m>
     [--glow-json JSON] [--turn DEG ...] <look A.glb> [<look B.glb> ...]
"""
import json
import math
import os
import sys

import numpy

import bmesh
import bpy
from mathutils import Matrix, Vector

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import mesh_repair  # noqa: E402
from prop_bake import *  # noqa: E402,F401,F403
from prop_bake import ROOT, args  # noqa: E402

NAME = args[1]
WIDTH = float(args[2])
rest = args[3:]
GLOW = None
TURNS = []
GLBS = []
i = 0
while i < len(rest):
    if rest[i] == "--glow-json":
        GLOW = json.loads(rest[i + 1])
        i += 2
    elif rest[i] == "--turn":
        TURNS.append(float(rest[i + 1]))
        i += 2
    else:
        GLBS.append(rest[i])
        i += 1


# The group's manifest: the gathering nodes', or another group's (SH_MANIFEST, set by generate_gathering.py --group).
MANIFEST = os.environ.get("SH_MANIFEST") or os.path.join(ROOT, "Tools", "LocalSpawn", "gathering_manifest.json")


def manifest_max_height():
    """The asset's height cap from the manifest (max_height), if it has one."""
    try:
        with open(MANIFEST, encoding="utf-8") as f:
            entry = next((a for a in json.load(f)["assets"] if a["asset"] == NAME), {})
        return entry.get("max_height")
    except (OSError, ValueError):
        return None


MAX_HEIGHT = manifest_max_height()


def manifest_metal_floor():
    """Where the asset's metal starts (manifest metal_floor, 0-1), or None: the asset has no metal at all.
    UltraTex paints metallic onto rock, wood and moss too (Iron's host rock ~0.7, Sticks' wood 1.0), which makes them
    shine like metal; only an ore keeps its metallic, remapped so everything under the floor becomes 0."""
    try:
        with open(MANIFEST, encoding="utf-8") as f:
            entry = next((a for a in json.load(f)["assets"] if a["asset"] == NAME), {})
        return entry.get("metal_floor")
    except (OSError, ValueError):
        return None


METAL_FLOOR = manifest_metal_floor()


def look_value(look_key, key):
    """A per-look manifest setting (looks[i][key] for the look whose key matches), or None."""
    looks = manifest_value("looks") or []
    return next((l.get(key) for l in looks if l.get("key") == look_key), None)


def manifest_value(key):
    try:
        with open(MANIFEST, encoding="utf-8") as f:
            return next((a for a in json.load(f)["assets"] if a["asset"] == NAME), {}).get(key)
    except (OSError, ValueError):
        return None


# How much of the metal taken away from rock under the floor darkens its colour (0-1). A surface at metallic m shows
# its base colour only as reflection; as a matte rock it is lit diffusely by base * (1 - m), so dropping the false metal
# without darkening leaves a pale rock (Iron's host rock went from dark to pale grey).
DIELECTRIC_DARKEN = manifest_value("dielectric_darken") or 0.0
ROUGHNESS = manifest_value("roughness")


def manifest_glow():
    """The asset's glow from the manifest, which wins over --glow-json (it can change while a batch is running)."""
    try:
        with open(MANIFEST, encoding="utf-8") as f:
            return next((a for a in json.load(f)["assets"] if a["asset"] == NAME), {}).get("glow")
    except (OSError, ValueError):
        return None


GLOW = manifest_glow() or GLOW  # the manifest is the source of truth


def import_look(path, key, turn, coll):
    """One GLB as a single mesh object, normalised: widest side WIDTH, pivot on the ground under its middle."""
    before = set(bpy.data.objects)
    bpy.ops.import_scene.gltf(filepath=path)
    meshes = [o for o in bpy.data.objects if o not in before and o.type == 'MESH']
    for o in [o for o in bpy.data.objects if o not in before and o.type != 'MESH']:
        bpy.data.objects.remove(o)
    for o in meshes:
        o.matrix_world = o.matrix_world.copy()
        for c in list(o.users_collection):
            c.objects.unlink(o)
        coll.objects.link(o)
    obj = join(meshes, f"{NAME} {key}") if len(meshes) > 1 else meshes[0]
    obj.name = obj.data.name = f"{NAME} {key}"
    select_only([obj])
    bpy.ops.object.transform_apply(location=True, rotation=True, scale=True)
    if manifest_value("lay_flat"):
        lay_flat(obj)
    obj.data.transform(Matrix.Rotation(math.radians(turn), 4, 'Z'))
    xs = [v.co.x for v in obj.data.vertices]
    ys = [v.co.y for v in obj.data.vertices]
    zs = [v.co.z for v in obj.data.vertices]
    widest = max(max(xs) - min(xs), max(ys) - min(ys))
    scale = WIDTH / widest
    if MAX_HEIGHT and (max(zs) - min(zs)) * scale > MAX_HEIGHT:
        scale = MAX_HEIGHT / (max(zs) - min(zs))  # a tall look (a spire, a slab on end) isn't scaled up by its width
    obj.data.transform(Matrix.Diagonal((scale, scale, scale, 1.0)) @
                       Matrix.Translation((-(min(xs) + max(xs)) / 2, -(min(ys) + max(ys)) / 2, -min(zs))))
    # Its own UVs become "grain" (what its imported maps sit on); the shared atlas is laid out by atlas_uvs.
    obj.data.uv_layers[0].name = "grain"
    for material in obj.data.materials:
        for n in material.node_tree.nodes:
            if n.type == 'TEX_IMAGE' and not n.inputs["Vector"].links:
                uv = material.node_tree.nodes.new("ShaderNodeUVMap")
                uv.uv_map = "grain"
                material.node_tree.links.new(uv.outputs["UV"], n.inputs["Vector"])
            if n.type == 'NORMAL_MAP':
                n.uv_map = "grain"
        # Height for parallax: the generated maps have none, so crevices (occlusion of the shape itself) are low.
        crevice = material.node_tree.nodes.new("ShaderNodeAmbientOcclusion")
        crevice.only_local = True
        crevice.samples = 16
        crevice.inputs["Distance"].default_value = WIDTH * 0.04
        lift = material.node_tree.nodes.new("NodeReroute")
        material.node_tree.links.new(crevice.outputs["AO"], lift.inputs[0])
        lift.label = "SH Height"
        # Metallic from the ORM's blue, for the ORM bake (prop_bake reads an "SH Metal" node).
        bsdf = next((n for n in material.node_tree.nodes if n.type == 'BSDF_PRINCIPLED'), None)
        metal_out = None
        if bsdf is not None and bsdf.inputs["Metallic"].links and METAL_FLOOR is not None:
            remap = material.node_tree.nodes.new("ShaderNodeMapRange")
            remap.inputs["From Min"].default_value = METAL_FLOOR
            remap.inputs["From Max"].default_value = 1.0
            remap.clamp = True
            material.node_tree.links.new(bsdf.inputs["Metallic"].links[0].from_socket, remap.inputs["Value"])
            metal_out = remap.outputs["Result"]
            above = look_value(key, "metal_above")
            if above is not None:
                # The look's metallic can't tell ore from rock (UltraTex made Iron B all metal): only what is above
                # this fraction of the height (its crystal crown) stays metal.
                tree = material.node_tree
                position = tree.nodes.new("ShaderNodeNewGeometry")
                xyz = tree.nodes.new("ShaderNodeSeparateXYZ")
                tree.links.new(position.outputs["Position"], xyz.inputs["Vector"])
                crown = tree.nodes.new("ShaderNodeMapRange")
                height = (max(zs) - min(zs)) * scale
                crown.inputs["From Min"].default_value = height * (above - 0.04)
                crown.inputs["From Max"].default_value = height * (above + 0.04)
                crown.clamp = True
                tree.links.new(xyz.outputs["Z"], crown.inputs["Value"])
                masked = tree.nodes.new("ShaderNodeMath")
                masked.operation = 'MULTIPLY'
                tree.links.new(metal_out, masked.inputs[0])
                tree.links.new(crown.outputs["Result"], masked.inputs[1])
                metal_out = masked.outputs["Value"]
            tag = material.node_tree.nodes.new("NodeReroute")
            strength = manifest_value("metal_strength")
            if strength is not None:
                # A crystal is mostly glass with a metallic sheen: fully metal, Moonsilver's pale crystals mirrored the
                # dark ground through the follow-the-player reflection probe and read dark grey in game. The mask
                # (metal_out) still places the ore's polish, its glow and the darkened rock; only metallic is scaled.
                scaled = material.node_tree.nodes.new("ShaderNodeMath")
                scaled.operation = 'MULTIPLY'
                scaled.inputs[1].default_value = strength
                material.node_tree.links.new(metal_out, scaled.inputs[0])
                material.node_tree.links.new(scaled.outputs["Value"], tag.inputs[0])
            else:
                material.node_tree.links.new(metal_out, tag.inputs[0])
            tag.label = "SH Metal"
            if DIELECTRIC_DARKEN > 0 and bsdf.inputs["Base Color"].links:
                tree = material.node_tree
                lost = tree.nodes.new("ShaderNodeMath")  # m * (1 - r): the metal this pixel lost
                lost.operation = 'MULTIPLY'
                keep = tree.nodes.new("ShaderNodeMath")
                keep.operation = 'SUBTRACT'
                keep.inputs[0].default_value = 1.0
                tree.links.new(metal_out, keep.inputs[1])
                tree.links.new(bsdf.inputs["Metallic"].links[0].from_socket, lost.inputs[0])
                tree.links.new(keep.outputs["Value"], lost.inputs[1])
                factor = tree.nodes.new("ShaderNodeMath")  # 1 - k * lost
                factor.operation = 'MULTIPLY_ADD'
                tree.links.new(lost.outputs["Value"], factor.inputs[0])
                factor.inputs[1].default_value = -DIELECTRIC_DARKEN
                factor.inputs[2].default_value = 1.0
                darken = tree.nodes.new("ShaderNodeMix")
                darken.data_type = 'RGBA'
                darken.blend_type = 'MULTIPLY'
                darken.inputs["Factor"].default_value = 1.0
                tree.links.new(bsdf.inputs["Base Color"].links[0].from_socket, darken.inputs["A"])
                tree.links.new(factor.outputs["Value"], darken.inputs["B"])
                tree.links.new(darken.outputs["Result"], bsdf.inputs["Base Color"])
        lift = manifest_value("ore_brighten")
        if bsdf is not None and lift and metal_out is not None and bsdf.inputs["Base Color"].links:
            # The ore's colour times lift where the ore is (Moonsilver's "pale" crystals were a mid grey, 0.6).
            tree = material.node_tree
            factor = tree.nodes.new("ShaderNodeMath")  # 1 + (lift - 1) * mask
            factor.operation = 'MULTIPLY_ADD'
            tree.links.new(metal_out, factor.inputs[0])
            factor.inputs[1].default_value = lift - 1.0
            factor.inputs[2].default_value = 1.0
            brighten = tree.nodes.new("ShaderNodeMix")
            brighten.data_type = 'RGBA'
            brighten.blend_type = 'MULTIPLY'
            brighten.inputs["Factor"].default_value = 1.0
            tree.links.new(bsdf.inputs["Base Color"].links[0].from_socket, brighten.inputs["A"])
            tree.links.new(factor.outputs["Value"], brighten.inputs["B"])
            tree.links.new(brighten.outputs["Result"], bsdf.inputs["Base Color"])
        if bsdf is not None and ROUGHNESS:
            set_roughness(material.node_tree, bsdf, metal_out)
    for poly in obj.data.polygons:
        poly.use_smooth = True
    return obj


WHEELS = manifest_value("wheels") or []
HUBS = {}  # wheel look -> its hub, found from the cut wheel


def cut_wheels(obj):
    """obj and, for each of the manifest's wheels, the faces inside its drum (radius, width about the hub, the axle
    along x) cut away into their own object '<obj> Wheel N'. A face goes by its centre; the cut is where the hub meets
    the axle, inside the wheel, where neither part shows it."""
    parts = [obj]
    # "remove": boxes [x0, x1, y0, y1, z0, z1] cut out of the model (the barrow's crossbar, where its wheel goes).
    for box in manifest_value("remove") or []:
        bm = bmesh.new()
        bm.from_mesh(obj.data)
        gone = [f for f in bm.faces if box[0] <= f.calc_center_median().x <= box[1] and box[2] <= f.calc_center_median().y <= box[3]
                and box[4] <= f.calc_center_median().z <= box[5]]
        bmesh.ops.delete(bm, geom=gone, context='FACES')
        bmesh.ops.delete(bm, geom=[v for v in bm.verts if not v.link_faces], context='VERTS')
        bm.to_mesh(obj.data)
        bm.free()
        print("REMOVED", len(gone), "faces in", box)
    for k, wheel in enumerate(WHEELS):
        hub, radius, width = Vector(wheel["hub"]), wheel["radius"], wheel["width"]

        def inside(c):
            return abs(c.x - hub.x) <= width / 2 and math.hypot(c.y - hub.y, c.z - hub.z) <= radius

        part = obj.copy()
        part.data = obj.data.copy()
        part.name = part.data.name = f"{obj.name} Wheel {k + 1}"
        for c in obj.users_collection:
            c.objects.link(part)
        for target, keep in ((part, True), (obj, False)):
            bm = bmesh.new()
            bm.from_mesh(target.data)
            bmesh.ops.delete(bm, geom=[f for f in bm.faces if inside(f.calc_center_median()) != keep], context='FACES')
            bmesh.ops.delete(bm, geom=[v for v in bm.verts if not v.link_faces], context='VERTS')
            bm.to_mesh(target.data)
            bm.free()
        co = numpy.empty(len(part.data.vertices) * 3, dtype=numpy.float32)
        part.data.vertices.foreach_get("co", co)
        co = co.reshape(-1, 3)
        lo, hi = co.min(axis=0), co.max(axis=0)
        # The tyre is round: the middle of its extent is the hub, half its height the radius the game rolls on.
        HUBS[part.name] = Vector(((lo + hi) / 2).tolist())
        print("WHEEL", part.name, "hub", tuple(round(v, 3) for v in HUBS[part.name]), "radius", round(float(hi[2] - lo[2]) / 2, 3),
              "across", round(float(hi[1] - lo[1]) / 2, 3), "width", round(float(hi[0] - lo[0]), 3), len(part.data.polygons), "faces")
        parts.append(part)
    return parts


def onto_hubs(variants):
    """After the bake: each wheel's mesh centred on its hub and the object put there, so it spins about its own axle."""
    for obj in variants:
        hub = HUBS.get(obj.name)
        if hub is not None:
            obj.data.transform(Matrix.Translation(-hub))
            obj.location = hub


def lay_flat(obj):
    """manifest lay_flat: a long thin thing the shape model stood on a slant (the oar came out diagonal, 2 m up) laid
    down: its longest axis along x, its flattest up, the wider end (an oar's blade) at +x."""
    co = numpy.empty(len(obj.data.vertices) * 3, dtype=numpy.float64)
    obj.data.vertices.foreach_get("co", co)
    co = co.reshape(-1, 3)
    centre = co.mean(axis=0)
    _, _, axes = numpy.linalg.svd(co - centre, full_matrices=False)
    long, broad = axes[0], axes[1]
    up = numpy.cross(long, broad)
    rotation = Matrix((tuple(long), tuple(broad), tuple(up)))
    obj.data.transform(Matrix.Translation(-Vector(centre.tolist())))
    obj.data.transform(rotation.to_4x4())
    co = numpy.empty(len(obj.data.vertices) * 3, dtype=numpy.float64)
    obj.data.vertices.foreach_get("co", co)
    co = co.reshape(-1, 3)
    length = co[:, 0].max() - co[:, 0].min()
    ends = [co[co[:, 0] < co[:, 0].min() + length * 0.2], co[co[:, 0] > co[:, 0].max() - length * 0.2]]
    spans = [e[:, 1].max() - e[:, 1].min() for e in ends]
    if spans[0] > spans[1]:
        obj.data.transform(Matrix.Rotation(math.pi, 4, 'Z'))
    print("LAY FLAT", obj.name, "length", round(float(length), 3), "end spans", [round(float(x), 3) for x in spans])


def set_roughness(tree, bsdf, metal_out):
    """Roughness into the asset's ranges (manifest roughness: {"rock": [lo, hi], "ore": [lo, hi]}), keeping the
    generated variation inside them. UltraTex makes rock and wood glossy (Iron's rock 0.2, Sticks 0.27: wet-looking) and
    copper a mirror (0.02), which shows only a pin-point sun glint; matte rock with polished but not mirror ore catches
    the sun, the moon and torches as broad highlights on the metal alone."""
    socket = bsdf.inputs["Roughness"]
    source = socket.links[0].from_socket if socket.links else None

    def ranged(lo, hi):
        node = tree.nodes.new("ShaderNodeMapRange")
        node.inputs["To Min"].default_value = lo
        node.inputs["To Max"].default_value = hi
        if source is not None:
            tree.links.new(source, node.inputs["Value"])
        else:
            node.inputs["Value"].default_value = socket.default_value
        return node.outputs["Result"]

    rock = ranged(*ROUGHNESS["rock"])
    if "ore" in ROUGHNESS and metal_out is not None:
        blend = tree.nodes.new("ShaderNodeMix")
        blend.data_type = 'FLOAT'
        tree.links.new(metal_out, blend.inputs["Factor"])
        tree.links.new(rock, blend.inputs["A"])
        tree.links.new(ranged(*ROUGHNESS["ore"]), blend.inputs["B"])
        rock = blend.outputs["Result"]
    tree.links.new(rock, socket)


def emission_from_albedo(glow):
    """An emission map from the baked albedo: where it is close to glow["colour"] (hue mode, by direction in RGB, so
    brightness doesn't matter) or bright (bright mode), above glow["threshold"], tinted glow["tint"]."""
    folder = os.path.join(ART, NAME)
    albedo = bpy.data.images.load(os.path.join(folder, f"{NAME}_Albedo.png"))
    w, h = albedo.size
    px = numpy.empty(w * h * 4, dtype=numpy.float32)
    albedo.pixels.foreach_get(px)
    rgb = px.reshape(-1, 4)[:, :3]
    if glow["mode"] == "hue":
        # Closeness by hue angle (1 = same hue, 0 = opposite): a direction in RGB can't tell yellow-green moss from a
        # green glow (cosine ~0.93), the hue wheel can (~55 degrees apart).
        def hue(c):
            c = numpy.atleast_2d(c)
            hi, lo = c.max(axis=1), c.min(axis=1)
            d = hi - lo + 1e-5
            r, g, b = c[:, 0], c[:, 1], c[:, 2]
            h = numpy.where(hi == r, ((g - b) / d) % 6, numpy.where(hi == g, (b - r) / d + 2, (r - g) / d + 4))
            return h * 60.0
        dh = numpy.abs(hue(rgb) - hue(numpy.array(glow["colour"], dtype=numpy.float32))[0])
        closeness = 1.0 - numpy.minimum(dh, 360.0 - dh) / 180.0
        brightness = rgb.max(axis=1)
        saturation = (brightness - rgb.min(axis=1)) / (brightness + 1e-4)
        # Only what is lit: bright and strongly coloured (a glowing seam), not rock or moss that is merely that hue.
        bright = numpy.clip((brightness - glow.get("min_brightness", 0.45)) / 0.25, 0, 1)
        vivid = numpy.clip((saturation - glow.get("min_saturation", 0.35)) / 0.25, 0, 1)
        strength = numpy.clip((closeness - glow["threshold"]) / (1.0 - glow["threshold"]), 0, 1) * bright * vivid
    elif glow["mode"] == "metal":
        # Where the ore is metal (the ORM's blue, baked at half size: scaled up to the albedo's), in its own colour.
        orm = bpy.data.images.load(os.path.join(folder, f"{NAME}_ORM.png"))
        orm.colorspace_settings.name = 'Non-Color'
        orm.scale(w, h)
        metal = numpy.empty(w * h * 4, dtype=numpy.float32)
        orm.pixels.foreach_get(metal)
        metallic = metal.reshape(-1, 4)[:, 2]
        strength = numpy.clip((metallic - glow["threshold"]) / (1.0 - glow["threshold"]), 0, 1)
        own = rgb / (rgb.max(axis=1, keepdims=True) + 1e-4)  # the metal's own hue at full brightness
        tint = numpy.array(glow["tint"], dtype=numpy.float32)
        out = numpy.zeros((w * h, 4), dtype=numpy.float32)
        out[:, :3] = strength[:, None] * (own * 0.5 + tint[None, :] * 0.5)
        out[:, 3] = 1.0
        save_emission(out, w, h, folder)
        return
    else:
        luminance = rgb @ numpy.array([0.2126, 0.7152, 0.0722], dtype=numpy.float32)
        strength = numpy.clip((luminance - glow["threshold"]) / (1.0 - glow["threshold"]), 0, 1)
    tint = numpy.array(glow["tint"], dtype=numpy.float32)
    out = numpy.zeros((w * h, 4), dtype=numpy.float32)
    out[:, :3] = strength[:, None] * tint[None, :]
    out[:, 3] = 1.0
    save_emission(out, w, h, folder)


def save_emission(out, w, h, folder):
    img = bpy.data.images.new(f"{NAME}_Emission", w, h, alpha=False)
    img.colorspace_settings.name = 'sRGB'
    img.pixels.foreach_set(out.ravel())
    img.filepath_raw = os.path.join(folder, f"{NAME}_Emission.png")
    img.file_format = 'PNG'
    img.save()
    no_moss_where_glowing(out, w, h, folder)


LOD0_TRIANGLES = manifest_value("lod0_triangles") or 5000  # the most a look may have (close views)
# The atlas: 2048, or the asset's own (manifest texture_size: a building's 6 m needs more than a boulder's 2 m);
# SH_BAKE_SIZE overrides both, for a quick first look at a pipeline change.
TEXTURE_SIZE = int(os.environ.get("SH_BAKE_SIZE") or manifest_value("texture_size") or 2048)

# The game's top-down view (Assets/_Project/Scripts/Editor/Environment/ScreenBudget.cs, measured in Play): 147 pixels a
# metre at 2160p at the default zoom, 48 degree pitch; a target of 40 pixels per visible triangle (10 at 1080p, the 2x2
# quad GPUs shade); the projected box is ~60% covered. LOD0 is what the top-down view draws (no lower level inside it),
# so LOD0 is sized for that view: big enough to read, never denser than the screen can show.
PIXELS_PER_METRE, PITCH, PIXELS_PER_TRIANGLE, FILL = 147.0, math.radians(48.0), 40.0, 0.6
# The least a look starts its search from; shape_keeping_triangles then raises it until the shape holds (a fixed
# 150-350 shredded small rocks and mushroom caps).
SILHOUETTE_FLOOR = 300


def view_triangles(obj):
    """LOD0 triangles for obj from its size in the top-down view, between the silhouette floor and the manifest cap.
    The size is read from the vertices: obj.dimensions can be stale after the mesh is transformed (Copper Ore A came out
    at 3,284 triangles alone and 5,000 beside another look)."""
    co = numpy.empty(len(obj.data.vertices) * 3, dtype=numpy.float32)
    obj.data.vertices.foreach_get("co", co)
    co = co.reshape(-1, 3) * numpy.array(obj.scale, dtype=numpy.float32)
    x, y, z = (co.max(axis=0) - co.min(axis=0)).tolist()
    across, deep = max(x, y), min(x, y)
    area = FILL * PIXELS_PER_METRE ** 2 * across * (z * math.cos(PITCH) + deep * math.sin(PITCH))
    return int(max(SILHOUETTE_FLOOR, min(LOD0_TRIANGLES, area / (PIXELS_PER_TRIANGLE * 0.5))))


def budget(high):
    """The game's mesh: a copy of the generated one (welded at its glTF seams) decimated to the asset's budget
    (manifest lod0_triangles, 5000 by default: the scanned boulder nodes are 6000), its maps baked from the full
    generated mesh. The generated meshes came in at ~10k triangles whatever their size, a 0.4 m mushroom patch too."""
    name = high.name
    # Holes first, on the generated mesh itself: the bake's source and the game's mesh then carry the same patches
    # (a patch on the game's mesh alone would bake black: its rays find nothing). SH_NO_REPAIR=1 leaves it as it came.
    mended = None if os.environ.get("SH_NO_REPAIR") else mesh_repair.repair(high)
    if mended:
        for poly in high.data.polygons:
            poly.use_smooth = True
        print("REPAIR", name, mended)
    high.name = name + " (high)"  # first, so the copy can take the look's own name
    low = high.copy()
    low.data = high.data.copy()
    low.name = name
    for c in high.users_collection:
        c.objects.link(low)
    bm = bmesh.new()
    bm.from_mesh(low.data)
    bmesh.ops.remove_doubles(bm, verts=bm.verts, dist=1e-4)  # the glTF's seam splits only: a wider weld collapsed
    # thin mushroom caps into a broken, black-baked mesh (2026-11-09)
    bmesh.ops.triangulate(bm, faces=bm.faces)
    bm.to_mesh(low.data)
    bm.free()
    wanted = view_triangles(low)
    target, report = shape_keeping_triangles(low, wanted)
    print("BUDGET", low.name, len(low.data.polygons), "->", target, report)
    BUDGETS[name] = {"source": len(low.data.polygons), "view": wanted, "triangles": target,
                     "shape_limited": target > wanted * 1.05, "check": report}
    if len(low.data.polygons) > target:
        decimate_to(low, target)
    # What the game's mesh still has open (flat keys: ModelBudgetTests reads an entry as one brace-free block).
    still = mesh_repair.measure_object(low)
    BUDGETS[name].update(holes_generated=mended["holes_before"] if mended else still["holes"],
                         holes_filled=mended["filled"] if mended else 0, holes=still["holes"],
                         largest_hole=still["largest_hole"], non_manifold_edges=still["non_manifold_edges"])
    print("HOLES", name, still)
    return low


# How far a decimation may go: 95% of the original surface within 2% of the model's size of the decimated one, and the
# silhouette from the game's 48-degree camera at least 95% the same. Measured in a fraction of a second, no bake: a
# fixed budget shredded some generated meshes (mushroom patch at 1,341: 11% off, silhouette 0.73; small rocks at 948:
# 24% off) and wasted triangles on others.
SHAPE_DEVIATION, SHAPE_SILHOUETTE = 0.02, 0.95
BUDGETS = {}  # look -> its budget and why, written beside the textures (<Asset>_Budget.json) for ModelBudgetTests


def save_budgets():
    import prop_bake
    for look, entry in BUDGETS.items():
        entry["unwrap"] = "smart" if look in prop_bake.SMART_FALLBACK else "regions"
    with open(os.path.join(ART, NAME, f"{NAME}_Budget.json"), "w", encoding="utf-8") as f:
        json.dump({"note": "LOD0 triangles per look, by ingest_generated.py: the top-down view's budget, raised where a "
                           "decimation would break the shape (shape_limited)", "looks": BUDGETS}, f, indent=1)


def decimate_to(obj, target):
    decimate = obj.modifiers.new("Decimate", 'DECIMATE')
    decimate.ratio = min(1.0, target / max(1, len(obj.data.polygons)))
    select_only([obj])
    bpy.ops.object.modifier_apply(modifier=decimate.name)


def _tree(obj):
    from mathutils.bvhtree import BVHTree
    bm = bmesh.new()
    bm.from_mesh(obj.data)
    tree = BVHTree.FromBMesh(bm)
    bm.free()
    return tree


def _surface_points(obj, n=2500):
    obj.data.calc_loop_triangles()
    tris = obj.data.loop_triangles
    verts = obj.data.vertices
    areas = numpy.array([t.area for t in tris], dtype=numpy.float64)
    rng = numpy.random.default_rng(7)
    picks = rng.choice(len(tris), n, p=areas / areas.sum())
    points = []
    for i in picks:
        a, b, c = (verts[k].co for k in tris[i].vertices)
        r1, r2 = rng.random(), rng.random()
        if r1 + r2 > 1:
            r1, r2 = 1 - r1, 1 - r2
        points.append(a + (b - a) * r1 + (c - a) * r2)
    return points


def _silhouette(tree, lo, hi, res=80):
    """Which of res x res rays from the game's 48-degree camera hit the mesh."""
    pitch = math.radians(48.0)
    look = Vector((0.0, math.cos(pitch), -math.sin(pitch)))
    right = Vector((1.0, 0.0, 0.0))
    up = look.cross(right).normalized()
    centre = (lo + hi) * 0.5
    span = max(hi - lo) * 1.3
    mask = numpy.zeros((res, res), dtype=bool)
    for i in range(res):
        for j in range(res):
            start = centre + right * ((i / res - 0.5) * span) + up * ((j / res - 0.5) * span) - look * span * 3
            mask[i, j] = tree.ray_cast(start, look, span * 10)[0] is not None
    return mask


def shape_keeping_triangles(obj, wanted):
    """The fewest triangles, from wanted up, at which a collapse decimation keeps obj's shape (SHAPE_DEVIATION,
    SHAPE_SILHOUETTE), capped by the manifest's lod0_triangles; tried on copies, obj is left as it is."""
    source = len(obj.data.polygons)
    cap = min(source, LOD0_TRIANGLES)
    co = numpy.empty(len(obj.data.vertices) * 3, dtype=numpy.float32)
    obj.data.vertices.foreach_get("co", co)
    co = co.reshape(-1, 3)
    lo, hi = Vector(co.min(axis=0).tolist()), Vector(co.max(axis=0).tolist())
    size = max(hi - lo)
    tree = _tree(obj)
    points = _surface_points(obj)
    mask = _silhouette(tree, lo, hi)
    target = max(300, min(wanted, cap))
    while True:
        if target >= source:
            return source, "(kept whole)"
        trial = obj.copy()
        trial.data = obj.data.copy()
        for c in obj.users_collection:
            c.objects.link(trial)
        decimate_to(trial, target)
        trial_tree = _tree(trial)
        gaps = sorted((p - trial_tree.find_nearest(p)[0]).length for p in points)
        deviation = gaps[int(len(gaps) * 0.95)] / size
        trial_mask = _silhouette(trial_tree, lo, hi)
        overlap = (trial_mask & mask).sum() / max(1, (trial_mask | mask).sum())
        reached = len(trial.data.polygons)
        mesh = trial.data
        bpy.data.objects.remove(trial)
        bpy.data.meshes.remove(mesh)
        if deviation <= SHAPE_DEVIATION and overlap >= SHAPE_SILHOUETTE and reached <= target * 1.15:
            return target, f"(deviation {100 * deviation:.1f}%, silhouette {overlap:.3f})"
        if target >= cap:
            return cap, f"(cap; deviation {100 * deviation:.1f}%, silhouette {overlap:.3f})"
        target = min(cap, int(target * 1.35))


def albedo_is_black():
    path = os.path.join(ART, NAME, f"{NAME}_Albedo.png")
    if not os.path.exists(path):
        return False
    img = bpy.data.images.load(path, check_existing=False)
    px = numpy.empty(img.size[0] * img.size[1] * 4, dtype=numpy.float32)
    img.pixels.foreach_get(px)
    lit = (px.reshape(-1, 4)[:, :3].max(axis=1) > 0.02).mean()
    bpy.data.images.remove(img)
    return lit < 0.02


def no_moss_where_glowing(out, w, h, folder):
    """Clear the BlendMask's coverage (alpha: where the live moss grows) wherever the emission glows: the coverage is
    baked from up-facing surfaces, so moss grew in blotches on the Radiant Life Orb's glowing orb."""
    path = os.path.join(folder, f"{NAME}_BlendMask.png")
    if not os.path.exists(path):
        return
    mask = bpy.data.images.load(path)
    mask.colorspace_settings.name = 'Non-Color'
    mw, mh = mask.size
    px = numpy.empty(mw * mh * 4, dtype=numpy.float32)
    mask.pixels.foreach_get(px)
    px = px.reshape(mh, mw, 4)
    glow = out[:, :3].max(axis=1).reshape(h, w)
    sy, sx = h // mh, w // mw
    glow = glow[:mh * sy, :mw * sx].reshape(mh, sy, mw, sx).max(axis=(1, 3))  # the mask is half size
    px[:, :, 3] *= numpy.clip(1.0 - glow * 6.0, 0.0, 1.0)
    mask.pixels.foreach_set(px.ravel())
    mask.save()


def main():
    bpy.ops.wm.read_factory_settings(use_empty=True)
    coll = collection(NAME)
    if os.environ.get("SH_BUDGET_ONLY"):
        for k, path in enumerate(GLBS):
            budget(import_look(path, chr(65 + k), TURNS[k] if k < len(TURNS) else 0.0, coll))
        return

    def builder(c, from_high=True):
        highs = [import_look(path, chr(65 + k), TURNS[k] if k < len(TURNS) else 0.0, c) for k, path in enumerate(GLBS)]
        highs = [part for high in highs for part in cut_wheels(high)]
        lows = [budget(high) for high in highs]
        if from_high:
            return lows, highs
        for high in highs:
            bpy.data.objects.remove(high)
        return lows

    looks = make_asset(NAME, builder, TEXTURE_SIZE, coll, cavity_distance=0.15, collider=True, lods=(0.35, 0.1), unwrap='regions',
                       after_bake=onto_hubs)
    if albedo_is_black():
        # Thin double-sided shells (the mushroom patch's caps) send the high-to-low rays nowhere: every colour bake came
        # out black. The decimated copy keeps the generated texture coordinates, so it bakes from its own material.
        print("BAKE from the full mesh came out black: baking from the decimated mesh's own material")
        bpy.ops.wm.read_factory_settings(use_empty=True)
        coll = collection(NAME)
        looks = make_asset(NAME, lambda c: builder(c, from_high=False), TEXTURE_SIZE, coll, cavity_distance=0.15, collider=True,
                           lods=(0.35, 0.1), unwrap='regions', after_bake=onto_hubs)
    save_budgets()
    if GLOW:
        emission_from_albedo(GLOW)
    stage([(looks, WIDTH * 1.4)], row_spacing=WIDTH)
    camera((0.0, -WIDTH * 2.6, WIDTH * 2.4), (0.0, 0.0, WIDTH * 0.2), lens=40)
    render(os.path.join(os.path.dirname(GLBS[0]), f"{NAME} ingest preview.png"), 1600, 900)
    print("INGEST DONE", NAME, [o.name for o in looks])


if __name__ == "__main__":
    main()
